import java.util.*; import java.io.*; public class TestClass { static class Edge { int to, time, cost; Edge(int to, int time, int cost) { this.to = to; this.time = time; this.cost = cost; } } static class State implements Comparable<State> { int u, time, cost; List<Integer> path; State(int u, int time, int cost, List<Integer> path) { this.u = u; this.time = time; this.cost = cost; this.path = path; } public int compareTo(State o) { return Integer.compare(this.cost, o.cost); } } public static void main(String[] args) throws Exception { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); long K = Long.parseLong(br.readLine().trim()); int N = Integer.parseInt(br.readLine().trim()); int X = Integer.parseInt(br.readLine().trim()); List<List<Edge>> adj = new ArrayList<>(); for (int i = 0; i <= N; i++) adj.add(new ArrayList<>()); for (int i = 0; i < X; i++) { String[] parts = br.readLine().split("\\s+"); int u = Integer.parseInt(parts[0]); int v = Integer.parseInt(parts[1]); int t = Integer.parseInt(parts[2]); int c = Integer.parseInt(parts[3]); adj.get(u).add(new Edge(v, t, c)); adj.get(v).add(new Edge(u, t, c)); } int S = Integer.parseInt(br.readLine().trim()); int D = Integer.parseInt(br.readLine().trim()); PriorityQueue<State> pq = new PriorityQueue<>(); List<Integer> startPath = new ArrayList<>(); startPath.add(S); pq.add(new State(S, 0, 0, startPath)); long[] minCost = new long[N + 1]; Arrays.fill(minCost, Long.MAX_VALUE); while (!pq.isEmpty()) { State curr = pq.poll(); if (curr.cost >= minCost[curr.u]) continue; minCost[curr.u] = curr.cost; if (curr.u == D) { StringBuilder sb = new StringBuilder(); for (int i = 0; i < curr.path.size(); i++) { sb.append(curr.path.get(i)); if (i < curr.path.size() - 1) sb.append("->"); } System.out.println(sb.toString() + " " + curr.time + " " + curr.cost); return; } for (Edge e : adj.get(curr.u)) { int nextTime = curr.time + e.time + (curr.path.size() > 1 ? 1 : 0); long nextCost = curr.cost + e.cost + (curr.path.size() > 1 ? K : 0); List<Integer> nextPath = new ArrayList<>(curr.path); nextPath.add(e.to); pq.add(new State(e.to, nextTime, (int)nextCost, nextPath)); } } System.out.println("Error"); } }